package sqlite

import(
	"context";"database/sql";"encoding/json";"time"
	"github.com/developmentconexus-ops/aurora_project/internal/domain/authority"
	"github.com/developmentconexus-ops/aurora_project/internal/domain/portability"
	"github.com/developmentconexus-ops/aurora_project/internal/domain/project"
	"github.com/developmentconexus-ops/aurora_project/internal/ports"
)
func(s *Store)ExportLogicalState(ctx context.Context)(portability.StoreState,error){snap,err:=s.LoadCurrent(ctx);if err!=nil{return portability.StoreState{},err};out:=portability.StoreState{GoverningGeneration:snap.GoverningGeneration,Aurora:snap.Identity,Authority:portability.AuthorityBundle{CurrentRevision:authority.Revision(snap.CurrentAuthorityRevision)}};for _,p:=range snap.Projects{bundle:=portability.ProjectBundle{Project:p};rows,err:=s.db.QueryContext(ctx,`SELECT state_revision FROM project_state_revisions WHERE project_id=? ORDER BY state_revision`,p.ProjectID);if err!=nil{return out,err};var revisions []project.StateRevision;for rows.Next(){var r project.StateRevision;if err:=rows.Scan(&r);err!=nil{rows.Close();return out,err};revisions=append(revisions,r)};if err:=rows.Err();err!=nil{rows.Close();return out,err};_=rows.Close();for _,r:=range revisions{rev,err:=s.loadProjectStateRevision(ctx,p.ProjectID,r);if err!=nil{return out,err};bundle.Revisions=append(bundle.Revisions,*rev)};out.Projects=append(out.Projects,bundle)};rows,err:=s.db.QueryContext(ctx,`SELECT authority_state_json FROM authority_revisions ORDER BY authority_revision`);if err!=nil{return out,err};for rows.Next(){var raw string;if err:=rows.Scan(&raw);err!=nil{rows.Close();return out,err};var st authority.State;if err:=json.Unmarshal([]byte(raw),&st);err!=nil{rows.Close();return out,err};out.Authority.Revisions=append(out.Authority.Revisions,st)};if err:=rows.Err();err!=nil{rows.Close();return out,err};_=rows.Close();rows,err=s.db.QueryContext(ctx,`SELECT attempt_id,project_id,actor_id,requested_at,expected_state_revision,requested_state_json,proposed_next_action_json,authority_evaluation_ref,result,reason,accepted_state_revision FROM transition_attempts ORDER BY requested_at,attempt_id`);if err!=nil{return out,err};for rows.Next(){var a portability.TransitionAttempt;var requested string;var next,authRef sql.NullString;var expected,accepted sql.NullInt64;var at string;if err:=rows.Scan(&a.AttemptID,&a.ProjectID,&a.ActorID,&at,&expected,&requested,&next,&authRef,&a.Result,&a.Reason,&accepted);err!=nil{rows.Close();return out,err};a.RequestedAt,err=time.Parse(time.RFC3339Nano,at);if err!=nil{rows.Close();return out,err};if expected.Valid{r:=project.StateRevision(expected.Int64);a.ExpectedRevision=&r};if accepted.Valid{r:=project.StateRevision(accepted.Int64);a.AcceptedStateRevision=&r};a.RequestedState=json.RawMessage(requested);if next.Valid{a.ProposedNextAction=json.RawMessage(next.String)};if authRef.Valid{a.AuthorityEvaluationRef=authRef.String};out.Attempts=append(out.Attempts,a)};if err:=rows.Err();err!=nil{rows.Close();return out,err};_=rows.Close();rows,err=s.db.QueryContext(ctx,`SELECT record_id,kind,operation_id,project_id,state_revision,authority_revision,outcome,reason,details_json,created_at FROM records ORDER BY created_at,record_id`);if err!=nil{return out,err};for rows.Next(){var r portability.Record;var pidNull sql.NullString;var sr,ar sql.NullInt64;var details,at string;if err:=rows.Scan(&r.RecordID,&r.Kind,&r.OperationID,&pidNull,&sr,&ar,&r.Outcome,&r.Reason,&details,&at);err!=nil{rows.Close();return out,err};if pidNull.Valid{r.ProjectID=project.ProjectID(pidNull.String)};if sr.Valid{x:=project.StateRevision(sr.Int64);r.StateRevision=&x};if ar.Valid{x:=authority.Revision(ar.Int64);r.AuthorityRevision=&x};r.Details=json.RawMessage(details);r.CreatedAt,err=time.Parse(time.RFC3339Nano,at);if err!=nil{rows.Close();return out,err};out.Records=append(out.Records,r)};if err:=rows.Err();err!=nil{rows.Close();return out,err};_=rows.Close();return out,nil}
func(s *Store)BuildFreshFromExport(ctx context.Context,in ports.RestoreSnapshot)error{tx,err:=s.db.BeginTx(ctx,nil);if err!=nil{return err};defer tx.Rollback();var count int;if err:=tx.QueryRowContext(ctx,`SELECT COUNT(*) FROM core_state`).Scan(&count);err!=nil{return err};if count!=0{return ports.ErrRestoreTargetNotFresh};state:=in.State;if len(state.Authority.Revisions)==0{return sql.ErrNoRows};for _,st:=range state.Authority.Revisions{raw,err:=json.Marshal(st);if err!=nil{return err};var pred any;if st.PredecessorRevision!=nil{pred=uint64(*st.PredecessorRevision)};if _,err:=tx.ExecContext(ctx,`INSERT INTO authority_revisions(authority_revision,predecessor_revision,authority_state_json,changed_by,changed_at) VALUES(?,?,?,?,?)`,st.Revision,pred,string(raw),st.ChangedBy,st.ChangedAt.UTC().Format(time.RFC3339Nano));err!=nil{return err}};created:=state.Aurora.CreatedAt.UTC().Format(time.RFC3339Nano);if _,err:=tx.ExecContext(ctx,`INSERT INTO core_state(singleton_key,aurora_id,owner_operator_id,logical_schema_version,current_authority_revision,governing_generation,governing_descriptor_hmac,created_at,updated_at) VALUES('core',?,?,?,?,?,?,?,?)`,state.Aurora.AuroraID,state.Aurora.OwnerOperatorID,1,state.Authority.CurrentRevision,state.GoverningGeneration,in.GoverningMAC,created,created);err!=nil{return err};for _,bundle:=range state.Projects{p:=bundle.Project;var current any;if p.CurrentStateRevision!=nil{current=uint64(*p.CurrentStateRevision)};if _,err:=tx.ExecContext(ctx,`INSERT INTO projects(project_id,display_label,objective_summary,current_state_revision,created_at,updated_at) VALUES(?,?,?,?,?,?)`,p.ProjectID,p.DisplayLabel,p.ObjectiveSummary,current,p.CreatedAt.UTC().Format(time.RFC3339Nano),p.UpdatedAt.UTC().Format(time.RFC3339Nano));err!=nil{return err};for _,rev:=range bundle.Revisions{var pred any;if rev.PredecessorRevision!=nil{pred=uint64(*rev.PredecessorRevision)};var payload any;if len(rev.State.Payload)>0{payload=string(rev.State.Payload)};var next any;if rev.ProposedNextAction!=nil{raw,err:=json.Marshal(rev.ProposedNextAction);if err!=nil{return err};next=string(raw)};if _,err:=tx.ExecContext(ctx,`INSERT INTO project_state_revisions(project_id,state_revision,predecessor_revision,state_schema_version,state_kind,state_summary,state_payload_json,accepted_intent_ref,proposed_next_action_json,accepted_by_actor,accepted_at,transition_attempt_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`,rev.ProjectID,rev.Revision,pred,rev.State.SchemaVersion,rev.State.Kind,rev.State.Summary,payload,nullableString(rev.AcceptedIntentRef),next,rev.AcceptedByActor,rev.AcceptedAt.UTC().Format(time.RFC3339Nano),rev.TransitionAttemptID);err!=nil{return err}}};for _,a:=range state.Attempts{var expected,accepted any;if a.ExpectedRevision!=nil{expected=uint64(*a.ExpectedRevision)};if a.AcceptedStateRevision!=nil{accepted=uint64(*a.AcceptedStateRevision)};var next any;if len(a.ProposedNextAction)>0{next=string(a.ProposedNextAction)};if _,err:=tx.ExecContext(ctx,`INSERT INTO transition_attempts(attempt_id,project_id,actor_id,requested_at,expected_state_revision,requested_state_json,proposed_next_action_json,authority_evaluation_ref,result,reason,accepted_state_revision) VALUES(?,?,?,?,?,?,?,?,?,?,?)`,a.AttemptID,a.ProjectID,a.ActorID,a.RequestedAt.UTC().Format(time.RFC3339Nano),expected,string(a.RequestedState),next,nullableString(a.AuthorityEvaluationRef),a.Result,a.Reason,accepted);err!=nil{return err}};for _,r:=range state.Records{var pid,sr,ar any;if r.ProjectID!=""{pid=r.ProjectID};if r.StateRevision!=nil{sr=uint64(*r.StateRevision)};if r.AuthorityRevision!=nil{ar=uint64(*r.AuthorityRevision)};details:="{}";if len(r.Details)>0{details=string(r.Details)};if _,err:=tx.ExecContext(ctx,`INSERT INTO records(record_id,kind,operation_id,project_id,state_revision,authority_revision,outcome,reason,details_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)`,r.RecordID,r.Kind,r.OperationID,pid,sr,ar,r.Outcome,r.Reason,details,r.CreatedAt.UTC().Format(time.RFC3339Nano));err!=nil{return err}};return tx.Commit()}
